"""Handwritten allocation, storage-resource, and memory-operation contracts."""


def section(title, *paragraphs, rows=None, columns=None):
    result = {"title": title, "paragraphs": list(paragraphs)}
    if rows is not None:
        result["table"] = {"columns": columns or ["Interface", "Description"], "rows": rows}
    return result


def typename(name, header, summary, sections, covers=()):
    result = {"name": name, "header": header, "summary": summary, "sections": sections}
    if covers:
        result["covers"] = list(covers)
    return result


POLICY_OPERATIONS = section("Member functions", rows=[
    ["`allocate`, `create`", "Obtain raw storage. Counts and returned lengths are bytes. An alignment template argument or runtime argument selects the required address alignment."],
    ["`allocation_extent`", "Compute the logical byte grant for a request. The result describes the allocator protocol, which can expose fewer bytes than the underlying block."],
    ["`resize(old, bytes, preserve)`", "Return storage for the new request, preserving at most `min(preserve, old.len, result.len)` bytes. A changed address invalidates all pointers into the old block."],
    ["`grow(old, minimum)`", "Apply the policy's growth recommendation and resize while preserving the old grant."],
    ["`destroy`, `deallocate`", "Return raw storage through the matching allocator and alignment. These operations do not invoke object destructors."],
    ["`recommend(current, minimum)`", "Compute a policy growth request; the maximum `usize` value denotes arithmetic overflow."],
    ["`auto_size`, `get_grow`", "Report the policy's initial byte request and compatibility growth factor."],
    ["`stats`, `reset_stats`", "Read or reset optional allocator telemetry. Availability is reported by `stats().enabled`."],
])


def policy_allocator(name, header, policy, minimum, granularity, growth, alignment, purpose):
    return typename(name, header,
        f"A stateless byte allocator using `{policy}` and the selected `abc` heap backend. {purpose}", [
        section("Allocation policy",
            f"For a nonzero request, the default policy grants at least {minimum} bytes, rounded to {granularity}. A zero request returns an empty chunk. The default alignment is {alignment} bytes; explicit alignment must be a nonzero power of two.",
            f"`recommend` computes at least the requested minimum and the ceiling of {growth} times the current byte count, then applies the policy minimum and granularity. The policy template argument can replace these defaults.",
            "The reported grant is computed from the policy, rather than copied from the physical heap block size. Matching deallocation therefore uses allocator provenance and alignment instead of treating unused physical block space as part of the container's capacity."),
        POLICY_OPERATIONS,
        section("Complexity",
            "Policy arithmetic is constant time. Allocation and release have the selected heap backend's costs. An in-place resize does not copy the payload; a relocating resize is linear in the number of preserved bytes, in addition to allocation and release. Geometric recommendations describe a capacity policy; they do not make every backend operation constant time."),
        section("Notes",
            "The allocator object contains no per-instance pool. Copying or moving an allocator does not copy or move its allocations. Raw storage is uninitialized unless the selected backend or configuration explicitly clears it. `share` is deleted; the policy's `shareable` field does not supply shared ownership or synchronization for stored objects.",
            "Arithmetic overflow and invalid alignment are reported through the allocation exception facilities. A nonzero allocation that cannot be satisfied is an allocation failure. Successful `resize` or `grow` must replace the caller's old chunk descriptor; a copied descriptor never extends the allocation's lifetime."),
    ])


